const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.file}</svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const mark='<svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M7 25V7h6l12 18h-6L7 7" stroke="currentColor" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/><path d="M25 7v10" stroke="currentColor" stroke-width="3.5" stroke-linecap="round"/></svg>';
const sampleEN='Every useful AI action starts with a question of trust. Who is acting, what can they access, and when should a person stay in the loop?\n\n## Identity is the starting point\n\nAs agents move from answering questions to getting things done, identity becomes part of the workflow — not just the sign-in screen.\n\nA connected identity gives every action the context it needs:\n\n- A clear owner and a verifiable permission\n- The right account for the right destination\n- A meaningful confirmation before publishing\n\n> Give agents the ability to act, and people the confidence to stay in control.\n\n## From a draft to a deliberate action\n\nWith NyxID, a draft, its author, and the account that publishes it stay connected. Every action has a scope. Every published version has a history.';
const sampleZH='每一次有价值的 AI 行动，都始于一个关于信任的问题：谁在执行，可以访问什么，以及什么时候需要人来确认？\n\n## 身份，是行动的起点\n\n当 Agent 从回答问题走向完成工作，身份就成为工作流的一部分，而不仅仅是登录页面。\n\n一个可验证的身份，为每次行动提供清晰的上下文：\n\n- 明确的内容所有者与操作权限\n- 为目标平台选择正确的账号\n- 在发布之前，完成有意义的确认\n\n> 让 Agent 有能力行动，让人始终掌握决定权。\n\n## 从草稿，到一次确定的发布\n\n文章、署名作者和发布账号保持明确关联。每次操作都有范围，每个公开版本都有记录。';
const langData=(title,body,version=1,live=0)=>({title,body,savedTitle:title,savedBody:body,version,live,submitted:0,stale:false,liveSnapshot:live?{savedTitle:title,savedBody:body,version:live}:null,submittedSnapshot:null});
const articles=[
  {id:'identity',owner:'org',creator:'self',author:'Jing Chen',initials:'JC',color:'',category:'产品洞察',updated:'12 分钟前',status:'published',langs:{en:langData('From identity to action: a safer way for AI to work',sampleEN,8,7),zh:{...langData('从身份到行动：让 AI 安全地完成工作',sampleZH,4,4),stale:true}}},
  {id:'agent',owner:'org',creator:'self',author:'Jing Chen',initials:'JC',color:'',category:'开发者指南',updated:'48 分钟前',status:'draft',langs:{en:langData('Building your first identity-aware agent',sampleEN,3),zh:langData('构建第一个理解身份的 Agent',sampleZH,1)}},
  {id:'launch',owner:'org',creator:'other',author:'Alex Wu',initials:'AW',color:'purple',category:'产品更新',updated:'2 小时前',status:'submitted',langs:{en:{...langData('A new chapter for connected work',sampleEN,5),submitted:5}}},
  {id:'permissions',owner:'org',creator:'other',author:'Sarah Lin',initials:'SL',color:'blue',category:'工程实践',updated:'3 小时前',status:'submitted',langs:{en:{...langData('Permissions that move with your team',sampleEN,4),submitted:4},zh:langData('让权限跟上团队的变化',sampleZH,2,2)}},
  {id:'context',owner:'org',creator:'self',author:'Jing Chen',initials:'JC',color:'',category:'产品洞察',updated:'昨天 16:20',status:'draft',langs:{en:langData('Context is the new interface',sampleEN,2)}},
  {id:'design',owner:'org',creator:'other',author:'Alex Wu',initials:'AW',color:'purple',category:'设计手记',updated:'10 月 30 日',status:'published',langs:{en:langData('Designing for trust, one interaction at a time',sampleEN,6,6),zh:langData('为信任而设计，从每一次交互开始',sampleZH,3,3)}},
  {id:'oauth',owner:'org',creator:'self',author:'Jing Chen',initials:'JC',color:'',category:'开发者指南',updated:'10 月 29 日',status:'published',langs:{en:langData('OAuth, explained through real workflows',sampleEN,4,4)}},
  {id:'notes',owner:'org',creator:'self',author:'Jing Chen',initials:'JC',color:'',category:'团队手记',updated:'10 月 28 日',status:'draft',langs:{zh:langData('一周构建笔记：让复杂的工作更简单',sampleZH,2)}},
  {id:'personal',owner:'personal',creator:'self',author:'Jing Chen',initials:'JC',color:'',category:'个人随笔',updated:'今天 09:30',status:'draft',langs:{en:langData('The tools that stayed in my workflow',sampleEN,2),zh:langData('那些真正留在工作流里的工具',sampleZH,1)}}
];
const routeNames=['content','editor','publish','distribution','deliveries','analytics','connections','settings','members','guide','login','onboarding','blog','story'];
const connectionStates={org:{dev:'connected',hashnode:'unconfigured'},personal:{dev:'connected',hashnode:'unsupported'}};
const state={route:routeNames.includes(location.hash.slice(1).split('?')[0])?location.hash.slice(1).split('?')[0]:'content',workspace:'org',role:'publisher',articleId:'identity',lang:'en',tab:'all',query:'',languageFilter:'all',page:1,selected:new Set(),editorView:'markdown',rights:false,release:'idle',conflict:false,dev:'approval_needed',medium:'manual_action_needed',mediumUrl:'',originalOffline:false,connectionLost:false,events:[],theme:matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'};
Object.defineProperty(state,'role',{get(){return workspaces[state.workspace].role;},set(value){workspaces[state.workspace].role=value;}});
let toastTimer,releaseTimer,focusBeforeModal;
const current=()=>articles.find(a=>a.id===state.articleId)||articles[0];
function canReadLanguage(a,key){const l=a.langs[key];return accessibleWorkspace(a.owner)&&a.owner===state.workspace&&Boolean(l)&&(a.creator==='self'||Boolean(l.liveSnapshot)||(canPublish()&&Boolean(l.submittedSnapshot)));}
function readableLanguage(a,key){const l=a.langs[key];if(a.creator==='self')return l;const frozen=canPublish()&&l?.submittedSnapshot?l.submittedSnapshot:l?.liveSnapshot;if(!frozen)return null;return {...l,title:frozen.savedTitle,body:frozen.savedBody,savedTitle:frozen.savedTitle,savedBody:frozen.savedBody,version:frozen.version};}
function displayLanguage(a){const key=canReadLanguage(a,'en')?'en':'zh';return readableLanguage(a,key)||{savedTitle:'暂无可查看版本',savedBody:''};}
const language=()=>readableLanguage(current(),state.lang)||displayLanguage(current());
const ownerName=()=>workspaceLabel();
const canPublish=()=>canPublishOwner(state.workspace);
const canEdit=()=>site.signedIn&&accessibleWorkspace(state.workspace)&&current().owner===state.workspace&&current().creator==='self';
const dirty=()=>{const l=language();return l.title!==l.savedTitle||l.body!==l.savedBody;};
const snapshot=l=>Object.freeze({savedTitle:l.savedTitle,savedBody:l.savedBody,version:l.version});
for(const a of articles)for(const l of Object.values(a.langs))if(l.submitted)l.submittedSnapshot=snapshot(l);
const distributionStates=new Map();
function distributionState(){const key=state.articleId+':'+state.lang;if(!distributionStates.has(key)){const l=language();distributionStates.set(key,{dev:'not_started',medium:'not_started',hashnode:'not_started',hacker:'not_started',mediumUrl:'',originalOffline:false,connectionLost:false,events:[],devSnapshot:l.liveSnapshot?{...l.liveSnapshot}:null,mediumSnapshot:l.liveSnapshot?{...l.liveSnapshot}:null});}return distributionStates.get(key);}
for(const key of ['dev','medium','mediumUrl','originalOffline','connectionLost','events','devSnapshot','mediumSnapshot'])Object.defineProperty(state,key,{get(){return key==='connectionLost'?connectionStates[current().owner].dev!=='connected':distributionState()[key];},set(value){if(key==='connectionLost')connectionStates[current().owner].dev=value?'expired':'connected';else distributionState()[key]=value;}});
const canSubmit=()=>canEdit()&&current().owner===state.workspace;
function confirmationProblem(){if(current().owner!==state.workspace)return '文章与当前工作区不一致。';if(!canPublish()&&!canSubmit())return '只能提交自己创建的组织草稿。';if(state.conflict)return '请先处理版本冲突。';if(dirty())return '请先保存草稿，再确认确定版本。';if(!language().savedTitle.trim()||!language().savedBody.trim())return '请补全标题和正文后再继续。';return null;}
function publicationTarget(owner=state.workspace,lang=state.lang){const rootUrl=site.setupRequests?.[owner]?.rootUrl||`https://${workspaces[owner].slug}.chronoai.example/`;const host=new URL(rootUrl).hostname;return {id:owner+':'+lang,language:lang,host,rootUrl,url:rootUrl+lang+'/',displayAddress:host+'/'+lang+'/',label:lang==='en'?'English':'简体中文'};}
const sourceUrl=()=>`${publicationTarget(current().owner,state.lang).url}${current().id}`;
function interfaceLanguageControl(){return `<label class="interface-language">${icon('globe')}<span>界面</span><select data-ui-locale aria-label="界面语言"><option value="en" lang="en">English</option><option value="zh" lang="zh-CN">简体中文</option></select></label>`;}
const roleLabel=()=>state.workspace==='personal'?'个人作者':({publisher:'Publisher',admin:'Admin',member:'Member'}[state.role]);
const badge=(text,color='neutral',withDot=false)=>`<span class="badge ${color}">${withDot?'<span class="dot"></span>':''}${esc(text)}</span>`;
const btn=(text,action,style='',ic='',extra='')=>`<button class="btn ${style}" data-action="${action}" ${extra}>${ic?icon(ic):''}${text}</button>`;
function toast(message){clearTimeout(toastTimer);const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),3200);}
function modal(title,body,footer='',wide=false){focusBeforeModal=document.activeElement;document.getElementById('overlay-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2>${interfaceLanguageControl()}<button class="icon-btn" data-action="close-modal" aria-label="关闭对话框">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;document.querySelector('.modal button,.modal input,.modal select')?.focus();}
function closeModal(){document.getElementById('overlay-root').replaceChildren();if(focusBeforeModal?.isConnected)focusBeforeModal.focus();}
let confirmedAction=null;
function guard(action){if(!dirty()||state.route!=='editor'){action();return;}confirmedAction=()=>{const l=language();l.title=l.savedTitle;l.body=l.savedBody;action();};modal('还有未保存的编辑','<p>离开前可以继续编辑，或放弃本次修改。已经保存的草稿和线上版本不会改变。</p>',btn('继续编辑','close-modal')+btn('放弃修改并继续','confirm-discard','primary'));}
function navigate(route){if(!routeNames.includes(route)||route===state.route)return;guard(()=>{state.route=route;state.rights=false;state.release='idle';history.pushState(null,'',`#${route}`);render();window.scrollTo(0,0);});}
function openArticle(id,route='editor'){guard(()=>{state.articleId=id;state.lang=preferredArticleLanguage(current());state.editorView='markdown';state.conflict=false;state.route=route;state.rights=false;state.release='idle';history.pushState(null,'',`#${route}`);render();window.scrollTo(0,0);});}
function articleStatus(a){const l=a.langs.en||a.langs.zh;if(a.status==='offline')return badge('已下线','neutral',true);if(a.status==='submitted')return badge('待发布','amber',true);if(l.live&&l.version>l.live)return badge('有未发布更改','purple',true);if(a.status==='published')return badge('已发布','green',true);return badge('草稿','neutral',true);}
function visibleArticles(){return articles.filter(a=>a.owner===state.workspace&&(a.creator==='self'||Object.keys(a.langs).some(k=>canReadLanguage(a,k))));}
function appShell(content){
  const active={editor:'content',publish:'content',distribution:'deliveries'}[state.route]||state.route;
  const nav=(items)=>items.map(([r,label,i])=>`<button class="nav-item ${active===r?'active':''}" data-route="${r}" title="${label}" ${active===r?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${r==='content'?`<span class="nav-count">${visibleArticles().length}</span>`:''}</button>`).join('');
  return `<div class="shell"><aside class="sidebar"><a class="wordmark" href="#content" data-route="content" aria-label="ChronoAI 内容首页"><span class="brand-symbol">${mark}</span><span>ChronoAI<small>PUBLISHING STUDIO</small></span></a><button class="workspace-switch" data-action="workspace" aria-label="切换工作区"><span class="workspace-avatar">${workspaceKind(state.workspace)==='organization'?'C':'JC'}</span><span><strong>${esc(ownerName())}</strong><small>${workspaceKind(state.workspace)==='organization'?'组织':'个人'} · ${roleLabel()}</small></span>${icon('down')}</button><div class="nav-label">工作空间</div><nav class="nav" aria-label="工作区导航">${nav([['content','内容库','layers'],['deliveries','发布与任务','send'],['analytics','数据分析','chart']])}</nav><div class="sidebar-separator"></div><div class="nav-label">管理</div><nav class="nav" aria-label="工作区管理">${nav([['connections','连接与渠道','link'],['settings','站点与工作区','settings'],...(workspaceKind(state.workspace)==='organization'?[['members','成员与权限','user']]:[])])}</nav><div class="sidebar-foot">${nav([['guide','开始使用','help']])}<div class="connection-note"><span class="dot green"></span> Connected with <strong>NyxID</strong></div><button class="profile profile-button" data-action="account-menu"><span class="avatar">JC</span><span><strong>Jing Chen</strong><small>${roleLabel()}</small></span>${icon('more')}</button></div></aside><div class="app-body"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="mobile-nav" aria-label="打开导航">${icon('menu')}</button>${icon(workspaceKind(state.workspace)==='organization'?'building':'user')}<span>${esc(ownerName())}</span>${icon('chevron')}<span>${routeTitles[state.route]}</span></div><div class="top-actions">${interfaceLanguageControl()}<button class="text-link" data-route="blog">查看公开博客 ${icon('external')}</button><span class="top-divider"></span><button class="icon-btn" data-action="theme" aria-label="切换${state.theme==='light'?'深色':'浅色'}主题">${icon(state.theme==='light'?'moon':'sun')}</button><button class="icon-btn" data-action="notifications" aria-label="待办通知">${icon('bell')}</button><button class="avatar" data-action="account-menu" aria-label="账号菜单">JC</button></div></header><main class="main page-enter" id="main-content">${content}</main></div></div>${dock()}`;
}
function dock(){return `<nav class="prototype-dock full-dock" aria-label="原型演示工具"><button class="dock-label" data-action="sitemap"><strong>B</strong><span> 全站原型 · 示例数据</span></button><button class="dock-item" data-action="sitemap">${icon('grid')}页面地图</button><button class="dock-item" data-action="demo">${icon('settings')}场景演示</button></nav>`;}
function contentPage(){const all=visibleArticles();const count=key=>all.filter(a=>matchesArticleStatus(a,key)).length;return `<div class="page-heading"><div><div class="eyebrow" style="margin-bottom:7px">YOUR PUBLISHING SPACE</div><h1>内容库</h1><p>让好内容，以正确的身份抵达读者。</p></div><div class="heading-actions">${btn('导入 Markdown','import','import-btn','upload')}${btn('新建文章','new','primary','plus')}</div></div><div class="content-summary"><button class="summary-card panel" data-filter="draft"><span class="summary-icon">${icon('file')}</span><div><div class="label">创作中的草稿</div><div class="value">${count('draft')}<small>继续写下一个好想法</small></div></div>${icon('chevron')}</button><button class="summary-card panel" data-filter="submitted"><span class="summary-icon amber">${icon('clock')}</span><div><div class="label">${canPublish()?'等待发布的内容':'已提交的内容'}</div><div class="value">${count('submitted')}<small>${canPublish()?'准备好与世界见面':'等待发布者处理'}</small></div></div>${icon('chevron')}</button><button class="summary-card panel" data-filter="published"><span class="summary-icon green">${icon('globe')}</span><div><div class="label">已发布的文章</div><div class="value">${count('published')}<small>内容的影响力正在生长</small></div></div>${icon('chevron')}</button></div><div class="content-toolbar"><div class="tabs" aria-label="内容状态筛选">${[['all','全部内容'],['draft','我的草稿'],['submitted','待发布'],['published','已发布']].map(([key,label])=>`<button class="tab ${state.tab===key?'active':''}" data-filter="${key}" aria-pressed="${state.tab===key}">${label}<span class="tab-count">${count(key)}</span></button>`).join('')}</div><div class="list-tools"><label class="search">${icon('search')}<input id="search-input" type="search" placeholder="搜索标题或关键词" value="${esc(state.query)}" aria-label="搜索内容"><kbd>⌘ K</kbd></label><button class="btn" data-action="filter">${icon('filter')}${state.languageFilter==='all'?'筛选':state.languageFilter==='en'?'English':'中文'}</button></div></div><div id="list-region">${articleList()}</div><div class="info-strip">${icon('shield')}<span>当前以 <strong>${ownerName()}</strong> 身份管理内容。署名作者与内容归属分别记录。</span><button data-action="ownership">了解内容归属 ${icon('arrow')}</button></div>`;}
function filteredArticles(){return visibleArticles().filter(a=>Object.keys(a.langs).some(k=>canReadLanguage(a,k)&&(state.languageFilter==='all'||k===state.languageFilter)&&(state.tab==='all'||(state.tab==='published'?isPublic(a,k):state.tab==='draft'?a.creator==='self'&&['draft','changed'].includes(languageState(a,k)):languageState(a,k)===state.tab)))&&Object.keys(a.langs).filter(k=>canReadLanguage(a,k)).some(k=>{const l=readableLanguage(a,k);return (l.savedTitle+' '+l.savedBody).toLowerCase().includes(state.query.toLowerCase());}));}
function articleList(){const filtered=filteredArticles();const pages=Math.max(1,Math.ceil(filtered.length/6));state.page=Math.min(state.page,pages);const rows=filtered.slice((state.page-1)*6,state.page*6);return `${state.selected.size?`<div class="selection-bar">已选择 ${state.selected.size} 篇文章 ${btn('下载 Markdown','export-selected','sm soft','download')}${btn('清除选择','clear-selection','sm quiet')}</div>`:''}<section class="panel table-wrap" aria-label="文章列表">${rows.length?`<table class="content-table"><thead><tr><th><input class="check" type="checkbox" id="select-all" aria-label="选择当前页全部文章" ${rows.every(a=>state.selected.has(a.id))?'checked':''}></th><th class="title-cell">文章标题</th><th class="status-col">发布状态</th><th class="language-col">语言</th><th class="author-col">署名作者</th><th class="date-col">最近更新 ${icon('down')}</th><th></th></tr></thead><tbody>${rows.map(a=>`<tr data-article="${a.id}"><td><input class="check row-check" type="checkbox" value="${a.id}" aria-label="选择 ${esc(displayLanguage(a).savedTitle)}" data-i18n-label-prefix="选择文章：" data-i18n-label-content="${esc(displayLanguage(a).savedTitle)}" ${state.selected.has(a.id)?'checked':''}></td><td class="title-cell"><div class="title-group"><span class="row-doc">${icon('file')}</span><div><button class="article-title" data-open="${a.id}" style="padding:0;text-align:left"><span data-i18n-preserve>${esc(displayLanguage(a).savedTitle)}</span></button><div class="article-sub">${esc(a.category)}${a.langs.zh?.stale?`${icon('link')}<span style="color:var(--amber)">中文译文需要核对</span>`:`<span>·</span><span>${matchesArticleStatus(a,'submitted')?'已提交确定版本':a.creator==='self'?'由我创建':'组织内容'}</span>`}</div></div></div></td><td class="status-col">${articleStatus(a)}</td><td class="language-col"><div class="lang-pair">${canReadLanguage(a,'en')?'<span class="lang">EN</span>':''}${canReadLanguage(a,'zh')?`<span class="lang ${a.langs.zh.stale?'stale':''}">中${a.langs.zh.stale?' ·':''}</span>`:''}</div></td><td class="author-col"><div class="mini-avatars"><span class="avatar ${a.color}">${a.initials}</span>${a.author.split(' ')[0]}</div></td><td class="date-col secondary">${a.updated}</td><td><button class="icon-btn" data-more="${a.id}" aria-label="${esc(displayLanguage(a).savedTitle)} 更多操作" data-i18n-label-prefix="文章操作：" data-i18n-label-content="${esc(displayLanguage(a).savedTitle)}">${icon('more')}</button></td></tr>`).join('')}</tbody></table>`:`<div class="empty">${icon('search')}<h3>没有找到匹配的内容</h3><p>试试其他关键词，或清除筛选查看全部文章。</p>${btn('清除筛选','reset-filters')}</div>`}<div class="table-footer"><span>共 ${filtered.length} 篇内容${filtered.length?` · 显示 ${(state.page-1)*6+1}–${Math.min(state.page*6,filtered.length)} 篇`:''}</span><div class="pagination"><button data-page="${state.page-1}" ${state.page<=1?'disabled':''} aria-label="上一页">${icon('back')}</button>${Array.from({length:pages},(_,i)=>`<button class="${state.page===i+1?'active':''}" data-page="${i+1}" aria-label="第 ${i+1} 页">${i+1}</button>`).join('')}<button data-page="${state.page+1}" ${state.page>=pages?'disabled':''} aria-label="下一页">${icon('chevron')}</button></div></div></section>`;}
function articleTabs(active){return `<nav class="article-page-tabs" aria-label="文章页面"><button class="${active==='edit'?'active':''}" data-route="editor">编辑</button><button class="${active==='distribution'?'active':''}" data-route="distribution">发布与分发</button><button data-action="article-analytics">数据</button><button data-action="history">版本历史</button></nav>`;}
function editorPage(){const a=current(),l=language();return `<div class="editor-top"><button class="back-link" data-route="content">${icon('back')}返回内容库</button><div class="editor-state"><span id="save-indicator"><span class="dot ${dirty()?'':'green'}"></span> ${dirty()?'有未保存的修改':`草稿 v${l.version} · 已保存`}</span><span>·</span><span>${icon('lock')} 仅授权成员可见</span></div></div><div class="editor-meta-bar"><div class="editor-title-label"><h1>${canEdit()?'打磨下一个好想法':'查看已授权的版本'}</h1>${badge(l.live?(l.version>l.live?'有未发布更改':'已发布'):l.submitted?'已提交':'草稿',l.live&&l.version===l.live?'green':'purple')}</div><div class="heading-actions">${btn('保存草稿','save','','',!canEdit()?'disabled':'')}${btn(canPublish()?'准备发布':'提交发布','prepare-publish','primary',canPublish()?'arrow':'send',!canPublish()&&!canSubmit()?'disabled':'')}</div></div>${articleTabs('edit')}${state.conflict?`<div class="conflict-banner">${icon('info')}<div><strong>发现一个更新的版本</strong><p>本次输入已保留。查看差异后再决定使用哪个版本。</p></div>${btn('查看版本差异','conflict-detail','sm')}</div>`:''}<div class="editor-grid"><section class="panel editor-paper"><div class="editor-controls"><div class="language-tabs" aria-label="文章语言版本">${['en','zh'].map(key=>`<button class="language-tab ${state.lang===key?'active':''}" data-lang="${key}" aria-pressed="${state.lang===key}">${key==='en'?'EN · English':'中 · 简体中文'}${a.langs[key]?.stale?'<span class="dot" title="译文需要核对"></span>':''}${!a.langs[key]?icon('plus'):''}</button>`).join('')}</div><div class="segmented" aria-label="编辑视图"><button class="${state.editorView==='markdown'?'active':''}" data-editor-view="markdown">Markdown</button><button class="${state.editorView==='preview'?'active':''}" data-editor-view="preview">私有预览</button></div></div><div class="editor-destination">${icon('globe')}<div><span>当前原文站点</span><strong>${publicationTarget(a.owner,state.lang).displayAddress}</strong><small>只发布当前语言；另一语言独立保存与发布。</small></div>${btn('语言与站点','translations','sm quiet','link')}</div>${state.editorView==='markdown'?`<div class="format-toolbar" aria-label="格式工具栏"><button data-format="heading" aria-label="添加标题">H₂</button><span class="divider"></span><button data-format="bold" aria-label="加粗"><b>B</b></button><button data-format="italic" aria-label="斜体"><i>I</i></button><button data-format="quote" aria-label="引用">${icon('quote')}</button><span class="divider"></span><button data-format="link" aria-label="插入链接">${icon('link')}</button><button data-format="list" aria-label="项目列表">${icon('list')}</button><button data-format="code" aria-label="代码块">${icon('code')}</button><button data-action="image" aria-label="插入私有图片">${icon('image')}</button><span class="label">MARKDOWN SOURCE</span></div><div class="writing-area"><div class="eyebrow">${esc(a.category)} / ${state.lang==='en'?'ENGLISH':'简体中文'}</div><textarea id="article-title" class="title-input" rows="2" maxlength="250" aria-label="文章标题" ${!canEdit()?'readonly':''}>${esc(l.title)}</textarea><textarea id="markdown" class="markdown-input" spellcheck="false" aria-label="Markdown 正文" ${!canEdit()?'readonly':''}>${esc(l.body)}</textarea></div>`:`<div class="writing-area"><div class="preview-note">${icon('lock')}私有预览 · 已保存版本 v${l.version}${dirty()?' · 未包含当前未保存的修改':''} · 不计入阅读数据</div><article class="saved-preview"><h1><span data-i18n-preserve>${esc(l.savedTitle)}</span></h1>${renderMarkdown(l.savedBody)}</article></div>`}<div class="editor-paper-footer"><span id="word-count">${l.body.length.toLocaleString()} 字符 <span>·</span> 约 3 分钟阅读</span><span>${icon('shield')}Markdown 原文保留${btn('下载','export','sm quiet','download')}</span></div></section><aside class="editor-sidebar"><section class="panel aside-panel"><h2 class="aside-title">${icon('file')}文章信息</h2><div class="aside-field"><div class="field-label">内容归属</div><div class="field-value">${icon(workspaceKind(a.owner)==='organization'?'building':'user')} ${esc(workspaceLabel(a.owner))} ${badge(workspaceKind(a.owner)==='organization'?'组织':'个人','neutral')}</div></div><div class="aside-field"><div class="field-label">署名作者</div><div class="field-value"><span class="avatar ${a.color}">${a.initials}</span>${a.author}</div><p class="aside-note">署名不改变内容所有权。</p></div><div class="aside-field"><div class="field-label">当前语言</div><div class="field-value">${state.lang==='en'?'English':'简体中文'} ${badge('独立发布','neutral')}</div></div></section><section class="panel aside-panel"><h2 class="aside-title">${icon('history')}版本状态</h2><div class="version-box current"><span>当前草稿</span><small>v${l.version}${dirty()?' + 修改':''}</small></div><div class="version-box"><span>${l.live?'线上版本':'尚未发布'}</span><small>${l.live?`v${l.live} · 已公开`:'—'}</small></div><p class="aside-note">保存只更新草稿。发布确认后，线上版本才会改变。</p><button class="aside-action" data-action="history">查看版本历史 ${icon('arrow')}</button></section><section class="panel aside-panel"><h2 class="aside-title">${icon('globe')}关联语言</h2>${['en','zh'].map(key=>`<div class="mini-language-row"><span class="lang">${key==='en'?'EN':'中'}</span>${key==='en'?'English':'简体中文'}${badge(!a.langs[key]?'未创建':a.langs[key].stale?'需要核对':a.langs[key].live?'已发布':'草稿',a.langs[key]?.stale?'amber':a.langs[key]?.live?'green':'neutral')}</div>`).join('')}${a.langs.zh?.stale?'<div class="translation-note" style="margin-top:12px"><strong>原文已有更新</strong><p>中文关联的是较早版本。请核对译文后，单独保存与发布。</p></div>':''}<button class="aside-action" data-action="translations">查看语言关系 ${icon('arrow')}</button></section></aside></div>`;}
function renderMarkdown(body){let result='',listOpen=false;for(const line of body.split('\n')){if(line.startsWith('- ')){if(!listOpen){result+='<ul>';listOpen=true;}result+=`<li>${esc(line.slice(2))}</li>`;continue;}if(listOpen){result+='</ul>';listOpen=false;}if(line.startsWith('## '))result+=`<h2>${esc(line.slice(3))}</h2>`;else if(line.startsWith('> '))result+=`<blockquote>${esc(line.slice(2))}</blockquote>`;else if(line.trim())result+=`<p>${esc(line).replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>')}</p>`;}return result+(listOpen?'</ul>':'');}
function visual(){return '<div class="article-visual" aria-hidden="true"><div class="visual-copy">One identity.<br>Every possibility.<small>NYXID / CONNECTED WORK</small></div><div class="orbital"></div></div>';}
function publicPreview(frozen=null){const l=frozen||snapshot(language()),a=current();return `<div class="public-preview"><div class="publication-name"><span class="brand-symbol" style="width:18px;height:20px">${mark}</span>${workspaceKind(a.owner)==='organization'?'ChronoAI Journal':'Jing’s Notes'}<span class="mono">IDEAS. PEOPLE. POSSIBILITIES.</span></div><div class="eyebrow" style="color:var(--purple-text)">${esc(a.category)} · ${state.lang==='en'?'ENGLISH':'简体中文'}</div><h2><span data-i18n-preserve>${esc(l.savedTitle)}</span></h2><div class="preview-byline"><span class="avatar ${a.color}">${a.initials}</span><strong>${a.author}</strong><span>·</span><span>Nov 2, 2026</span><span>·</span><span>3 min read</span></div>${visual()}<div class="article-excerpt"><p><span data-i18n-preserve>${esc(l.savedBody.split('\n')[0])}</span></p><h3>${state.lang==='en'?'Identity is the starting point':'身份，是行动的起点'}</h3><p><span data-i18n-preserve>${esc(l.savedBody.split('\n').find(p=>p.startsWith('As agents')||p.startsWith('当 Agent'))||l.savedBody.split('\n')[0])}</span></p></div></div>`;}
function publishPage(){const a=current(),l=language(),publisher=canPublish();const ready=state.release==='published'||state.release==='submitted';return `<button class="back-link" data-route="editor">${icon('back')}返回编辑器</button><div class="review-heading" style="margin-top:22px"><div class="eyebrow">${publisher?'READY TO SHARE':'READY FOR YOUR TEAM'}</div><h1>${publisher?'确认发布':'提交发布'}</h1><p>${publisher?'核对这一次发布的内容、身份与目的地。':'提交当前已保存版本，交由有发布权限的成员处理。'}</p></div><div class="review-grid"><section class="panel review-preview"><div class="panel-header"><span>${icon('eye')} 内容预览</span><small>已保存版本 v${l.version} · ${state.lang==='en'?'English':'简体中文'}</small></div>${publicPreview()}</section><aside class="review-side">${ready?`<section class="success-panel"><div class="success-check">${icon('check')}</div><h2>${publisher?'原文已核验发布':'版本已提交'}</h2><p>${publisher?`v${l.live} 已作为当前线上版本。接下来可以为这篇文章安排分发。`:`提交的是 v${l.submitted}。继续编辑不会改变已提交的内容。`}</p>${btn(publisher?'查看分发详情':'返回内容库',publisher?'go-distribution':'go-content','primary full',publisher?'send':'arrow')}<p style="font-size:9px;margin-bottom:0">原型演示结果 · 未发送真实请求</p></section>`:`<section class="panel review-summary"><h3>${publisher?'发布摘要':'提交摘要'}</h3><div class="review-line"><span>内容所有者</span><span>${esc(workspaceLabel(a.owner))} ${badge(workspaceKind(a.owner)==='organization'?'组织':'个人','neutral')}</span></div><div class="review-line"><span>署名作者</span><span>${esc(a.author)}</span></div><div class="review-line"><span>发布语言</span><span>${state.lang==='en'?'English':'简体中文'}</span></div><div class="review-line"><span>确认版本</span><span class="mono">v${l.version}<small>${publisher&&l.live?`当前线上 v${l.live} 将被更新`:'后续编辑不会改变本次确认内容'}</small></span></div><div class="review-line"><span>本次动作</span><span>${publisher?(l.live?'更新原文':'首次发布'):'提交组织草稿'}</span></div><div class="section-line"></div><div class="field-label" style="margin-bottom:9px">${publisher?'发布到原文站点':'原文目标站点'}</div><div class="destination-card"><span class="platform-logo ghost">${icon('ghost')}</span><div><strong>${workspaceKind(a.owner)==='organization'?'ChronoAI Journal':'Jing’s Notes'}</strong><small>${state.lang==='en'?'en':'zh'}.${workspaceKind(a.owner)==='organization'?'chronoai':'jing'}.example</small></div>${icon('check')}</div><p class="aside-note" style="margin-top:10px">${publisher?'只发布当前语言；另一语言独立保存与发布。原文公开后再安排外部分发。':'本次只提交当前语言草稿，不会公开文章。'}</p>${publisher?`<div class="rights"><input class="check" id="rights-confirm" type="checkbox" ${state.rights?'checked':''}><label for="rights-confirm">我已核对当前版本，并确认拥有文字和图片的发布权利。</label></div>`:'<div style="height:18px"></div>'}${state.release==='processing'?'<div class="processing"><span class="spinner"></span>正在核验原文公开状态…</div>':btn(publisher?(l.live?'确认更新原文':'确认发布原文'):'确认提交当前版本','confirm-publish','primary full large',publisher?'globe':'send',(publisher&&!state.rights)||(!publisher&&!canSubmit())?'disabled':'')}<p class="review-footnote">${publisher?'按当前权限直接发布，无需另设编辑审核。':'Publisher 或 Admin 可处理这次提交。'}</p></section>`}<div class="calm-note">${icon('shield')}<span>${publisher?'这次确认仅针对 Ghost 原文。组织向外部平台自动写入时，仍需 NyxID Admin 对具体内容和动作授权。':'提交后仍可继续编辑草稿。新改动需要再次提交，才能进入新的发布版本。'}</span></div><button class="btn quiet full" data-action="export">${icon('download')}下载当前 Markdown 原文</button></aside></div>`;}
function platform(name){return `<span class="platform-logo ${name}">${name==='ghost'?icon('ghost'):name==='dev'?'DEV':name==='medium'?'M':name==='hashnode'?'<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M3 5a4 4 0 0 1 4-3h10a4 4 0 0 1 4 4v12a4 4 0 0 1-4 4H7a4 4 0 0 1-4-4Z"/><circle cx="12" cy="12" r="5" fill="white"/></svg>':'H'}</span>`;}
function devCard(){const disabled=!canPublish();let status=state.dev;if(state.connectionLost)status='connection_lost';else if(['approval_needed','ready'].includes(status)&&(!state.devSnapshot||state.devSnapshot.version!==language().live))status='outdated';const catalog={outdated:['版本待确认','amber','原文已经更新，需要新的分发确认','旧的内容确认和批准不能用于新版本。请重新核对内容、目标账号和动作。','确认新版本','renew-request'],ready:['准备分发','blue','使用自己的账号发布这篇内容','个人写入使用个人连接，不需要组织 Admin 批准。','确认个人分发','personal-distribute'],approval_needed:['待组织授权','amber','需要 NyxID Admin 批准这次写入','批准绑定本次内容、DEV 目标账号与“新建副本”动作。原文的发布权限不受影响。','查看授权请求','approval'],published:['已发布','green','这篇内容已在 DEV 公开','公开链接与原文来源已核验。更改线上副本需要重新确认相应内容与动作。','查看公开副本','dev-preview'],uncertain:['结果待核验','amber','平台可能已经收到请求','先核验现有结果，再决定下一步。核验前不会再次发送，以避免重复文章。','核验结果','reconcile'],connection_lost:['连接已失效','amber','需要重新连接原账号','请在 NyxID 恢复 ChronoAI / @chronoai-team 的连接。不会自动切换到其他账号。','查看重连指引','reconnect'],removed:['已移除','neutral','已知副本已核验移除','历史记录与来源关系仍然保留。','查看操作记录','delivery-history']};const [label,color,title,description,action,handler]=catalog[status];return `<section class="panel channel-card"><div class="channel-head">${platform('dev')}<div class="channel-name"><strong>DEV Community</strong><small>自动发布 · 全文副本</small></div>${badge(label,color,true)}</div><div class="channel-message ${color==='neutral'?'':color}"><strong>${title}</strong><p>${description}</p></div><div class="channel-details"><span>${icon(workspaceKind(current().owner)==='organization'?'building':'user')}${workspaceKind(current().owner)==='organization'?'ChronoAI':'Jing 的个人空间'}</span><span>${icon('user')}${workspaceKind(current().owner)==='organization'?'@chronoai-team':'@jing-demo'}</span><span>${icon('file')}原文 v${state.devSnapshot?.version||language().live||'—'}</span></div><div class="channel-actions"><button class="text-link" data-action="delivery-history">${icon('history')}操作记录</button><div style="display:flex;gap:7px">${status==='published'&&state.originalOffline?btn('移除已知副本','remove-copy','sm','',disabled?'disabled':''):''}${btn(action,handler,status==='approval_needed'?'sm soft':'sm','',(disabled&&handler!=='dev-preview'&&handler!=='delivery-history')||(state.originalOffline&&['approval','personal-distribute','renew-request'].includes(handler))?'disabled':'')}</div></div></section>`;}
function mediumCard(){const status=state.medium;const catalog={manual_action_needed:['待人工导入','blue','带上内容和来源，完成最后一步','已准备 Markdown、署名和原文链接。请到 Medium 完成导入，再记录投稿结果。'],submitted:['已提交','amber','已记录投稿，尚未确认公开','“已提交”不代表“已发布”。获得公开链接后，核验文章与原文来源。'],published:['已发布','green','公开副本已核验','Medium 链接和原文来源已核验，人工操作记录已保留。']};const [label,color,title,description]=catalog[status];return `<section class="panel channel-card"><div class="channel-head">${platform('medium')}<div class="channel-name"><strong>Medium</strong><small>辅助导入 · 需要人工操作</small></div>${badge(label,color,true)}</div><div class="channel-message ${color}"><strong>${title}</strong><p>${description}</p></div><div class="channel-details"><span>${icon('link')}保留原文来源</span><span>${icon('user')}署名 ${esc(current().author)}</span><span>${icon('globe')}${state.lang==='en'?'English':'简体中文'} · v${state.mediumSnapshot?.version||language().live}</span></div><div class="channel-actions"><button class="text-link" data-action="package">${icon('download')}获取投稿材料</button>${status==='manual_action_needed'?btn('记录投稿结果','medium-report','sm','',!canPublish()||state.originalOffline?'disabled':''):status==='submitted'?btn('核验公开链接','medium-verify','sm','',!canPublish()?'disabled':''):btn('查看公开副本','medium-preview','sm','external')}</div></section>`;}
function distributionPage(){const a=current(),l=language();const personal=state.workspace==='personal';const showChannels=canPublish()&&Boolean(l.live);return `<div class="editor-top"><button class="back-link" data-route="content">${icon('back')}返回内容库</button><div class="editor-state">${icon('clock')}状态更新于 16:42</div></div><div class="page-heading distribution-heading" style="margin:19px 0 24px"><div><div class="distribution-title"><h1>每个渠道，都有清晰的下一步。</h1></div><p>跟踪这篇文章的公开版本、分发进度与待办。</p></div><div class="heading-actions">${btn('刷新状态','refresh-distribution','','refresh')}</div></div><section class="panel source-summary">${platform('ghost')}<div class="source-text"><strong><span data-i18n-preserve>${esc(l.liveSnapshot?.savedTitle||l.savedTitle)}</span> ${badge(!l.live?'原文尚未发布':state.originalOffline?'原文已下线':'Ghost 原文已发布',!l.live||state.originalOffline?'neutral':'green',true)}</strong><p>${esc(workspaceLabel(a.owner))} · ${state.lang==='en'?'English':'简体中文'} · v${l.live||'—'} · ${sourceUrl().replace('https://','')}</p></div>${btn('查看原文','public-preview','sm','external')}</section>${!l.live?`<div class="calm-note" style="margin-bottom:20px">${icon('info')}这篇文章还没有公开版本。确认原文发布后，才能新建外部副本。</div>`:!showChannels?`<div class="calm-note" style="margin-bottom:20px">${icon('lock')}当前为普通组织成员。可以查看已公开原文，组织连接、分发操作与私有任务仅向有权限的成员开放。</div>`:state.lang==='zh'?`<div class="calm-note" style="margin-bottom:20px">${icon('info')}中文原文独立发布。外部分发初期仅支持英文，中文渠道需要完成政策与渲染验证。</div>`:state.originalOffline?`<div class="calm-note" style="margin-bottom:20px">${icon('info')}原文已下线，暂停新建和更新外部副本。已知副本的核验与移除仍按当前权限开放。</div>`:''}<div class="distribution-grid"><div><div class="section-heading"><h2>分发渠道 <span style="margin-left:5px">${showChannels&&state.lang==='en'?'2 个已配置':'—'}</span></h2><span>${state.lang==='en'?'EN / 英文内容':'中文内容'}</span></div><div class="channel-stack">${!showChannels||state.lang==='zh'?`<section class="panel empty">${icon('shield')}<h3>${!l.live?'先让原文与读者见面':!showChannels?'当前身份没有组织分发权限':'中文外部分发尚未启用'}</h3><p>${!l.live?'保存并确认原文发布后，再选择需要分发的平台。':!showChannels?'可返回自己的草稿继续创作，或查看已发布原文。':'英文和中文的发布状态保持独立。'}</p>${btn('返回编辑器','go-editor')}</section>`:`${personal?`<div class="calm-note">${icon('user')}个人工作区使用自己的连接；组织 Admin 批准要求不适用于个人写入。</div>`:''}${devCard()}${mediumCard()}<section class="panel channel-card compact"><div class="channel-head">${platform('hashnode')}<div class="channel-name"><strong>Hashnode</strong><small>${personal?'个人 Hashnode 未纳入当前范围':'自动发布 · 需组织 Pro publication'}</small></div>${btn(personal?'查看范围':'查看前置条件','hashnode','sm quiet','chevron')}</div></section><section class="panel channel-card compact"><div class="channel-head">${platform('hacker')}<div class="channel-name"><strong>HackerNoon</strong><small>辅助投稿 · 平台编辑审核</small></div>${btn('查看投稿要求','hackernoon','sm quiet','chevron')}</div></section>`}</div></div><aside class="distribution-aside editor-sidebar"><section class="panel aside-panel"><h2 class="aside-title">这篇文章的进度</h2><div class="side-stat"><span><span class="dot" style="color:var(--green)"></span>原文已公开</span><strong>${!l.live||state.originalOffline?'0':'1'}</strong></div><div class="side-stat"><span><span class="dot" style="color:var(--amber)"></span>需要处理</span><strong>${showChannels&&state.lang==='en'?articleTaskCounts().pending:'—'}</strong></div><div class="side-stat"><span><span class="dot" style="color:var(--blue)"></span>外部已发布</span><strong>${showChannels&&state.lang==='en'?articleTaskCounts().published:'—'}</strong></div><div class="section-line" style="margin:13px 0"></div><p class="aside-note">各渠道独立记录。某个平台失败，不影响其他平台的成功结果。</p></section><section class="panel aside-panel"><h2 class="aside-title">${icon('history')}最近动态</h2><ol class="timeline">${state.events.map(e=>`<li>${esc(e)}<small>刚刚 · 当前演示</small></li>`).join('')}${showChannels&&state.lang==='en'?`<li>已准备 Medium 投稿材料<small>16:42 · Jing Chen</small></li>${personal?'':'<li>已请求 DEV 精确授权<small>16:41 · 等待组织 Admin</small></li>'}`:''}${l.live?`<li>原文公开状态核验通过<small>16:40 · Ghost</small></li><li>确认文章版本与发布身份<small>16:39 · <span class="mono">v${l.live}</span></small></li>`:'<li>已创建文章草稿<small>尚未发布</small></li>'}</ol><button class="aside-action" data-action="delivery-history">查看完整记录 ${icon('arrow')}</button></section><section class="panel aside-panel"><div class="side-help"><strong>${icon('info')} 已提交 ≠ 已发布</strong><p>辅助投稿需要人工跟进。获得公开链接并完成核验后，才会显示“已发布”。</p></div></section></aside></div>`;}
function resizeTitle(){const field=document.getElementById('article-title');if(field){field.style.height='auto';field.style.height=field.scrollHeight+'px';}}
const pageRenderers={content:contentPage,editor:editorPage,publish:publishPage,distribution:distributionPage};
function render(){ensureSession();document.documentElement.dataset.theme=state.theme;document.title=(routeTitles[state.route]||'Publishing Studio')+' · ChronoAI';const page=(pageRenderers[state.route]||contentPage)();document.getElementById('app').innerHTML=['login','onboarding','blog','story'].includes(state.route)?standaloneShell(page):appShell(page);resizeTitle();}
function updateList(){document.getElementById('list-region').innerHTML=articleList();}
function updateEditFeedback(){const l=language();const indicator=document.getElementById('save-indicator');if(indicator)indicator.innerHTML=`<span class="dot ${dirty()?'':'green'}"></span> ${dirty()?'有未保存的修改':`草稿 v${l.version} · 已保存`}`;const counter=document.getElementById('word-count');if(counter)counter.textContent=`${l.body.length.toLocaleString()} 字符 · 约 ${Math.max(1,Math.ceil(l.body.length/900))} 分钟阅读`;}
function save(){if(!canEdit()){toast('只有草稿作者可以编辑此版本。');return;}if(!language().title.trim()||!language().body.trim()){toast('请填写标题和 Markdown 正文后再保存。');return;}if(state.conflict){actions['conflict-detail']();return;}if(!dirty()){toast('当前草稿已是最新保存版本。');return;}const l=language();l.savedTitle=l.title;l.savedBody=l.body;l.version+=1;current().updated='刚刚';if(state.lang==='en'&&current().langs.zh)current().langs.zh.stale=true;render();toast(`草稿 v${l.version} 已保存；线上${l.live?`仍是 v${l.live}`:'尚未发布'}。`);}
function exportMarkdown(article=current()){const l=canReadLanguage(article,state.lang)?readableLanguage(article,state.lang):displayLanguage(article);download(`${l.savedTitle.replace(/[^\p{L}\p{N}]+/gu,'-').slice(0,70)}.md`,l.savedBody);}
function download(name,content){const url=URL.createObjectURL(new Blob([content],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function showPreview(title='公开阅读效果',frozen=language().liveSnapshot){if(!frozen){toast('这篇文章尚未发布；可在编辑器查看私有预览。');return;}modal(title,`<p class="prototype-explainer">阅读效果预览 · 已公开版本 v${frozen.version} · 示例内容。</p>${publicPreview(frozen)}`,btn('关闭预览','close-modal'),true);}
function recordEvent(message){state.events.unshift(message);state.events=state.events.slice(0,4);}
const actions={
  theme(){state.theme=state.theme==='light'?'dark':'light';render();},
  workspace(){modal('选择工作区',`<p>每个工作区拥有独立的内容、站点和连接。</p>${[['org','C','ChronoAI','组织工作区 · '+roleLabel()],['personal','JC','Jing 的个人空间','个人内容 · 仅自己可见']].map(([id,avatar,name,sub])=>`<button class="choice ${state.workspace===id?'selected':''}" data-workspace="${id}"><span class="workspace-avatar">${avatar}</span><span><strong>${name}</strong><small>${sub}</small></span>${state.workspace===id?icon('check'):''}</button>`).join('')}`);},
  demo(){modal('原型演示设置',`<p class="prototype-explainer">以下控件仅用于体验角色和异常状态，不是正式产品的权限管理。所有变化只保存在本页内存中。</p><div class="modal-field"><label for="demo-role">组织演示身份</label><select id="demo-role"><option value="publisher" ${state.role==='publisher'?'selected':''}>Publisher · 可发布，不管理组织权限</option><option value="member" ${state.role==='member'?'selected':''}>Member · 组织投稿，个人可发布</option><option value="admin" ${state.role==='admin'?'selected':''}>Admin · 发布与角色管理</option></select></div><div class="field-label" style="margin-bottom:10px">异常与恢复场景</div><div class="demo-control-grid">${btn('编辑版本冲突','demo-conflict','','history')}${btn('DEV 结果未知','demo-uncertain','','info')}${btn('原文已下线','demo-offline','','globe')}${btn('连接失效','demo-connection','','link')}${btn('恢复正常场景','demo-reset','','refresh')}</div>`,btn('完成','close-modal','primary'));},
  filter(){modal('筛选内容',`<div class="modal-field"><label for="filter-language">文章语言</label><select id="filter-language"><option value="all" ${state.languageFilter==='all'?'selected':''}>全部语言</option><option value="en" ${state.languageFilter==='en'?'selected':''}>包含 English</option><option value="zh" ${state.languageFilter==='zh'?'selected':''}>包含简体中文</option></select></div>`,btn('取消','close-modal')+btn('应用筛选','apply-filter','primary'));},
  'apply-filter'(){state.languageFilter=document.getElementById('filter-language').value;state.page=1;closeModal();render();},
  'reset-filters'(){state.query='';state.tab='all';state.languageFilter='all';state.page=1;render();},
  'clear-selection'(){state.selected.clear();updateList();},
  'export-selected'(){const chosen=visibleArticles().filter(a=>state.selected.has(a.id));if(!chosen.length)return;download('selected-articles.md',chosen.map(a=>{const l=displayLanguage(a);return l.savedBody;}).join('\n\n---\n\n'));toast(`已下载 ${chosen.length} 篇示例文章的合并 Markdown。`);},
  new(){guard(()=>{const id='draft-'+Date.now();articles.unshift({id,owner:state.workspace,creator:'self',author:'Jing Chen',initials:'JC',color:'',category:'未分类',updated:'刚刚',status:'draft',langs:{en:langData('Untitled story','',1)}});state.articleId=id;state.lang='en';state.route='editor';state.editorView='markdown';history.pushState(null,'','#editor');render();});},
  import(){guard(()=>{modal('导入 Markdown',`<p>导入到 <strong>${ownerName()}</strong>。文件仅在本地原型内读取，原文不会上传到任何服务。</p><div class="modal-field"><label for="import-file">选择 .md 文件（最大 2 MB）</label><input id="import-file" type="file" accept=".md,text/markdown"></div><div class="modal-field"><label for="import-language">文章语言</label><select id="import-language"><option value="en">English</option><option value="zh">简体中文</option></select></div><div class="form-error" id="import-error"></div>`,btn('取消','close-modal')+btn('导入为草稿','do-import','primary'));});},
  async 'do-import'(){const file=document.getElementById('import-file').files[0];const error=document.getElementById('import-error');if(!file||file.size>2000000){error.textContent='请选择不超过 2 MB 的 Markdown 文件。';return;}const importOwner=state.workspace,importLang=document.getElementById('import-language').value;try{const body=new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(await file.arrayBuffer());if(!site.signedIn||state.workspace!==importOwner||!accessibleWorkspace(importOwner)){toast('导入期间工作区已变化，请在目标工作区重新导入。');return;}const lang=importLang;const title=body.match(/^#\s+(.+)$/m)?.[1]||file.name.replace(/\.md$/i,'');const id='import-'+Date.now();articles.unshift({id,owner:state.workspace,creator:'self',author:'Jing Chen',initials:'JC',color:'',category:'导入文章',updated:'刚刚',status:'draft',langs:{[lang]:langData(title,body,1)}});closeModal();state.articleId=id;state.lang=lang;state.route='editor';state.editorView='markdown';history.pushState(null,'','#editor');render();toast('Markdown 已在本地导入为草稿。');}catch{error.textContent='无法读取文件，请使用 UTF-8 编码的 Markdown。';}},
  save:()=>save(),
  'prepare-publish'(){const problem=confirmationProblem();if(problem){toast(problem);return;}navigate('publish');},
  'confirm-publish'(){
    if(state.release==='processing')return;
    const problem=confirmationProblem();if(problem){toast(problem);return;}
    if(canPublish()&&!state.rights){toast('请先确认文字和图片的发布权利。');return;}
    const frozen=snapshot(language()),id=state.articleId,lang=state.lang,owner=state.workspace;
    if(!canPublish()){language().submitted=frozen.version;language().submittedSnapshot=frozen;current().status='submitted';state.release='submitted';render();return;}
    state.release='processing';render();
    releaseTimer=setTimeout(()=>{if(id!==state.articleId||lang!==state.lang||owner!==state.workspace)return;if(!canPublish()){state.release='idle';render();toast('发布权限已变化，本次演示任务已阻断。');return;}current().langs[lang].live=frozen.version;current().langs[lang].liveSnapshot=frozen;current().status='published';state.originalOffline=false;state.release='published';recordEvent('原文 v'+frozen.version+' 已核验发布');render();},1000);
  },
  'go-distribution'(){navigate('distribution');},'go-content'(){navigate('content');},'go-editor'(){navigate('editor');},
  export(){exportMarkdown();},
  history(){const l=language();modal('版本历史',`<p>当前只展示本身份有权查看的版本。保存草稿不会改变已提交或线上内容。</p><div class="history-item"><div><strong>v${l.version} · 当前草稿</strong><small>${current().author} · 今天 16:28</small></div>${badge('已保存','purple')}</div>${l.submitted?`<div class="history-item"><div><strong>v${l.submitted} · 已提交版本</strong><small>提交后内容保持冻结</small></div>${badge('已提交','amber')}</div>`:''}${l.live?`<div class="history-item"><div><strong>v${l.live} · 当前线上版本</strong><small>已确认版本 · Ghost 原文</small></div>${badge('已公开','green')}</div>`:''}<div class="history-item"><div><strong>v${Math.max(1,l.version-1)} · 较早修订</strong><small>示例修订记录</small></div></div>`,btn('下载当前源文','export','','download')+btn('完成','close-modal','primary'));},
  translations(){modal('两种语言，各自发布',`<p>English 与简体中文是关联的独立文章。原文变化时，译文会提示需要核对；不会自动替换或发布。</p>${['en','zh'].map(k=>`<div class="history-item"><div><strong>${k==='en'?'English':'简体中文'}</strong><small>${current().langs[k]?`草稿 v${current().langs[k].version} · 线上 ${current().langs[k].live?'v'+current().langs[k].live:'未发布'}`:'尚未创建'}</small></div>${badge(current().langs[k]?.stale?'需要核对':'独立版本',current().langs[k]?.stale?'amber':'neutral')}</div>`).join('')}`,btn('明白了','close-modal','primary'));},
  'public-preview'(){if(state.originalOffline){toast('原文已下线。已知外部副本仍可按权限核验或移除。');return;}showPreview();},'dev-preview'(){showPreview('DEV 副本阅读效果',state.devSnapshot);},'medium-preview'(){showPreview('Medium 副本阅读效果',state.mediumSnapshot);},
  ownership(){modal('内容归属与署名',`<p><strong>内容所有者</strong>决定文章属于哪个个人或组织，以及可使用的发布站点和连接。</p><p><strong>署名作者</strong>表示文章由谁创作，不授予组织发布权限。</p><p>切换工作区只改变当前查看的内容，不会迁移已有文章。</p>`,btn('明白了','close-modal','primary'));},
  'renew-request'(){if(!canPublish()||!language().liveSnapshot||state.originalOffline)return;modal('确认新的分发版本',`<p>${state.devSnapshot?'原文已从 v'+state.devSnapshot.version+' 更新到 v'+language().live:'原文 v'+language().live+' 已公开'}。请确认本次分发版本；原有批准不会复用。</p><div class="review-line"><span>目标账号</span><span>${workspaceKind(current().owner)==='organization'?'ChronoAI / @chronoai-team':'Jing / @jing-demo'}</span></div><div class="review-line"><span>本次动作</span><span>新建全文副本</span></div>`,btn('取消','close-modal')+btn('确认新版本','renew-confirm','primary'));},
  'renew-confirm'(){state.devSnapshot={...language().liveSnapshot};state.dev=workspaceKind(current().owner)==='organization'?'approval_needed':'ready';recordEvent('已确认新的分发版本，旧批准不再适用');closeModal();render();},
  approval(){if(!canPublish()||state.originalOffline||!language().liveSnapshot||state.devSnapshot?.version!==language().live)return;modal('DEV · 精确授权请求',`<p class="prototype-explainer">演示状态：等待 NyxID 组织 Admin。此原型不会向 NyxID 发送请求。</p><div class="review-line"><span>内容所有者</span><span>ChronoAI</span></div><div class="review-line"><span>确认内容</span><span>${state.lang==='en'?'English':'简体中文'} · 原文 v${state.devSnapshot?.version||language().live||'—'}</span></div><div class="review-line"><span>目的地账号</span><span>DEV / @chronoai-team</span></div><div class="review-line"><span>动作</span><span>新建全文副本</span></div><p>批准只适用于这些内容和目标。改变内容、账号或动作后需要新的授权。Publisher 身份不能代替 Admin 批准。</p>`,btn('关闭','close-modal')+btn('模拟 Admin 批准回执','simulate-approval','primary'));},
  'personal-distribute'(){if(!canPublish()||current().owner!=='personal'||!language().liveSnapshot||state.originalOffline||state.connectionLost)return;state.devSnapshot={...language().liveSnapshot};state.dev='published';recordEvent('个人 DEV 副本已核验发布');render();toast('演示：使用个人连接完成分发，无组织批准要求。');},
  'simulate-approval'(){if(!canPublish()||state.originalOffline||state.connectionLost||state.devSnapshot?.version!==language().live){toast('当前权限、原文版本或连接状态不允许新建副本。');return;}closeModal();state.devSnapshot=state.devSnapshot||{...language().liveSnapshot};state.dev='published';recordEvent('已收到精确批准；DEV 副本核验公开');render();toast('演示：收到 Admin 批准回执后完成发布，未进行真实操作。');},
  package(){if(!canPublish()||!language().liveSnapshot)return;if(state.medium==='manual_action_needed'&&!state.originalOffline)state.mediumSnapshot={...language().liveSnapshot};modal('Medium 投稿材料',`<p>请在 Medium 完成导入或投稿，并保留原文来源。获取材料不会自动发表文章。</p><div class="package-preview">${esc(`# ${state.mediumSnapshot?.savedTitle||language().liveSnapshot.savedTitle}\n\n作者：${current().author}\n原文：${sourceUrl()}\n\n${(state.mediumSnapshot?.savedBody||language().liveSnapshot.savedBody).slice(0,430)}…`)}</div>`,btn('关闭','close-modal')+btn('下载投稿材料','download-package','primary','download'),true);},
  'download-package'(){if(!canPublish()||!language().liveSnapshot)return;download('medium-submission.md',`# ${state.mediumSnapshot?.savedTitle||language().liveSnapshot.savedTitle}\n\nAuthor: ${current().author}\nOriginal: ${sourceUrl()}\n\n${state.mediumSnapshot?.savedBody||language().liveSnapshot.savedBody}`);toast('示例投稿材料已下载；仍需人工在平台操作。');},
  'medium-report'(){if(!canPublish()||state.originalOffline)return;if(state.mediumSnapshot?.version!==language().live){toast('原文已更新，请先重新获取当前版本的投稿材料。');return;}modal('记录 Medium 投稿结果',`<p>记录已在外部平台完成的操作。提交记录会显示为“已提交”，不会标记为已公开。</p><div class="modal-field"><label for="medium-url">投稿或编辑链接（可选）</label><input id="medium-url" type="url" placeholder="https://medium.com/…" value="${esc(state.mediumUrl)}"></div><div class="form-error" id="medium-error"></div>`,btn('取消','close-modal')+btn('记录为已提交','save-medium-report','primary'));},
  'save-medium-report'(){const value=document.getElementById('medium-url').value.trim();if(value&&!/^https:\/\//i.test(value)){document.getElementById('medium-error').textContent='请填写 HTTPS 链接，或留空。';return;}state.mediumUrl=value;state.medium='submitted';recordEvent('已记录 Medium 投稿 · 尚未确认公开');closeModal();render();toast('Medium 已记录为“已提交”，公开状态仍待核验。');},
  'medium-verify'(){if(!canPublish())return;modal('核验 Medium 公开链接',`<p>生产流程需要核对公开文章和来源链接。本原型仅模拟这一结果。</p><div class="modal-field"><label for="verify-url">公开文章链接</label><input id="verify-url" type="url" value="https://medium.com/@demo/from-identity-to-action"></div><div class="form-error" id="verify-error"></div>`,btn('取消','close-modal')+btn('模拟公开核验通过','verify-medium','primary'));},
  'verify-medium'(){const value=document.getElementById('verify-url').value.trim();if(!/^https:\/\//i.test(value)){document.getElementById('verify-error').textContent='请填写 HTTPS 公开链接。';return;}state.medium='published';state.mediumUrl=value;recordEvent('Medium 公开链接与来源核验通过');closeModal();render();toast('演示：已核验公开链接。');},
  reconcile(){if(!canPublish())return;state.dev='published';recordEvent('只读核验找到已有 DEV 副本，未重复发送');render();toast('演示核验：找到原有公开副本，没有重复发送。');},
  'remove-copy'(){if(!canPublish())return;modal('移除已知 DEV 副本',`<p>将对已知的 DEV 副本请求移除。原文下线不妨碍清理已知副本；仍需验证当前权限、原账号及适用授权。</p><p class="prototype-explainer">此处仅模拟授权核验通过后的移除结果。</p>`,btn('取消','close-modal')+btn('模拟批准并移除','confirm-remove','danger'));},
  'confirm-remove'(){if(!canPublish()||state.connectionLost){toast('当前权限或连接不允许移除。');return;}state.dev='removed';recordEvent('已知 DEV 副本已核验移除');closeModal();render();},
  reconnect(){modal('恢复原账号连接',`<p>在 NyxID 中重新连接 <strong>ChronoAI / @chronoai-team</strong>，再返回查看状态。</p><p>连接失效不会切换到其他账号，也不会自动重新发送内容。</p>`,btn('关闭','close-modal')+btn('模拟原账号已重连','simulate-reconnect','primary'));},
  'simulate-reconnect'(){state.connectionLost=false;closeModal();render();toast('演示：原账号连接已恢复，任务状态保持不变。');},
  'refresh-distribution'(){toast('已读取本地演示状态，未请求真实平台。');},
  'delivery-history'(){modal('发布与分发记录',`<p>每个平台保留独立的操作与核验结果。</p>${state.events.map(e=>`<div class="history-item"><div>${esc(e)}<small>刚刚 · 本地演示</small></div></div>`).join('')}<div class="history-item"><div>原文公开状态核验通过<small>16:40 · Ghost · 已确认版本</small></div>${badge('完成','green')}</div><div class="history-item"><div>DEV 精确授权请求已创建<small>16:41 · 新建副本 · 指定连接</small></div>${badge('已记录','neutral')}</div><details style="margin-top:16px;font-size:11px"><summary>诊断详情</summary><p class="mono" style="margin-top:10px">Trace ID: prototype-demo-20261102<br>所有记录均为示例数据</p></details>`,btn('关闭','close-modal'));},
  'demo-conflict'(){closeModal();state.route='editor';state.conflict=true;history.pushState(null,'','#editor');render();toast('已切换到版本冲突场景；当前输入保留。');},
  'demo-uncertain'(){closeModal();state.dev='uncertain';state.route='distribution';history.pushState(null,'','#distribution');render();},
  'demo-offline'(){closeModal();state.originalOffline=true;state.dev='published';state.route='distribution';history.pushState(null,'','#distribution');render();},
  'demo-connection'(){closeModal();state.connectionLost=true;state.route='distribution';history.pushState(null,'','#distribution');render();},
  'demo-reset'(){state.conflict=false;state.dev=current().owner==='personal'?'ready':'approval_needed';state.medium='manual_action_needed';state.originalOffline=false;state.connectionLost=false;state.events=[];closeModal();render();toast('已恢复默认演示状态。');},
  'conflict-detail'(){modal('处理版本冲突',`<p class="prototype-explainer">本地编辑仍保留在输入区，未覆盖服务器版本。这里演示服务器出现了更新版本的情形。</p><div class="history-item"><div><strong>本次编辑</strong><small><span data-i18n-preserve>${esc(language().title)}</span> · ${language().body.length} 字符</small></div>${badge('已保留','purple')}</div><div class="history-item"><div><strong>服务器版本 v${language().version+1}</strong><small>示例：另一入口更新了文章结尾</small></div></div><p style="margin-top:15px">可继续保留本次输入，或明确放弃后载入服务器版本。</p>`,btn('保留本次编辑','close-modal')+btn('放弃并载入服务器版','reload-conflict','primary'));},
  'reload-conflict'(){const l=language();l.version+=1;l.savedBody+='\n\n'+(state.lang==='en'?'A clear audit trail makes the next step easier to trust.':'清晰的记录，让下一次行动更值得信任。');l.body=l.savedBody;l.title=l.savedTitle;state.conflict=false;closeModal();render();toast('已载入示例服务器版本。');},
  'confirm-discard'(){closeModal();const fn=confirmedAction;confirmedAction=null;fn?.();},
  'close-modal':closeModal,
  image(){modal('私有图片',`<p>正式产品中，图片属于当前文章并受相同权限保护。本原型提供一个图片语法示例，不会上传文件。</p><div class="package-preview">![图片说明](private-image-placeholder.png)</div>`,btn('取消','close-modal')+btn('插入语法示例','insert-image','primary'));},
  'insert-image'(){if(!canEdit())return;language().body+='\n\n![图片说明](private-image-placeholder.png)';closeModal();state.editorView='markdown';render();toast('已插入示例语法，请保存草稿。');},
  connections(){modal('当前工作区连接',`<p>外部账号统一在 NyxID 管理。当前页面展示连接状态，不接收或显示凭证。</p><div class="history-item"><div><strong>DEV / @chronoai-team</strong><small>ChronoAI 指定组织连接</small></div>${badge(state.connectionLost?'需重连':'已配置',state.connectionLost?'amber':'green')}</div><div class="history-item"><div><strong>Medium</strong><small>辅助投稿 · 由人完成平台操作</small></div>${badge('人工流程','blue')}</div>`,btn('关闭','close-modal'));},
  notifications(){modal('需要处理的事项',`<p>待办仅展示当前身份有权处理的任务。</p>${canPublish()?'<div class="history-item"><div><strong>DEV 分发等待组织 Admin 授权</strong><small>指定内容、账号和新建动作</small></div></div><div class="history-item"><div><strong>Medium 投稿需要人工操作</strong><small>材料已准备，尚未提交</small></div></div>':'<p>当前没有新的个人待办。可以继续创作自己的组织草稿。</p>'}`,btn('关闭','close-modal')+(canPublish()?btn('查看分发详情','modal-distribution','primary'):''));},
  'modal-distribution'(){closeModal();navigate('distribution');},
  guide(){modal('原型浏览指南',`<p>底部导航可以直接切换四个页面。也可以从内容列表打开文章，保存草稿，再进入发布确认。</p><p>右上角切换浅／深色；左侧切换工作区；底部设置可以演示普通成员、发布者和异常状态。</p><p class="prototype-explainer">所有内容、身份、账号和发布结果均为示例。未接入业务 API。</p>`,btn('开始体验','close-modal','primary'));},
  'analytics-info'(){modal('数据分析 · 后续页面',`<p>本次聚焦内容列表、双语编辑、发布确认和分发详情四页。</p><p>后续数据页将独立展示阅读趋势、来源与分发结果，并保留来源、更新时间和 Unavailable 状态。</p>`,btn('返回原型','close-modal','primary'));},
  'article-analytics'(){actions['analytics-info']();},
  'settings-info'(){modal('工作区设置 · 后续页面',`<p>本次未展开设置页面。组织 Admin 管理发布权限，Publisher 可发布但不自动获得角色管理权。</p><p>当前演示身份：<strong>${roleLabel()}</strong>。角色模拟可从底部原型设置打开。</p>`,btn('关闭','close-modal'));},
  hashnode(){modal('Hashnode 发布前置条件',`<p>当前需求支持组织自动发布，需要合适的 Pro publication、正确的账号权限，以及 NyxID 中的组织连接。</p><p>组织自动写入还需要 Admin 对具体内容、目标和动作授权。个人 Hashnode 不在本轮范围内。</p>`,btn('明白了','close-modal','primary'));},
  hackernoon(){modal('HackerNoon 辅助投稿',`<p>准备稿件、署名、图片与原文链接，再由人完成投稿和跟进审核。</p><p>公司域名原文通常需要公司账号。编辑接受与公开时间由平台决定，提交不等于发布。</p>`,btn('明白了','close-modal','primary'));}
};

document.addEventListener('click',event=>{
  const target=event.target.closest('button,a');
  if(target?.disabled)return;
  if(target?.dataset.route){event.preventDefault();navigate(target.dataset.route);return;}
  if(target?.dataset.action){event.preventDefault();actions[target.dataset.action]?.();return;}
  if(target?.dataset.open){openArticle(target.dataset.open);return;}
  if(target?.dataset.more){state.articleId=target.dataset.more;state.lang=canReadLanguage(current(),'en')?'en':'zh';modal('文章操作',`<p><span data-i18n-preserve>${esc(language().savedTitle)}</span></p>`,btn('下载原文','export','','download')+btn('打开文章','open-selected','primary'));return;}
  if(target?.dataset.filter){state.tab=target.dataset.filter;state.page=1;state.selected.clear();render();return;}
  if(target?.dataset.page){state.page=Number(target.dataset.page);updateList();return;}
  if(target?.dataset.lang){const lang=target.dataset.lang;if(lang===state.lang)return;if(!canEdit()&&!canReadLanguage(current(),lang)){toast('当前身份无法查看这个语言版本。');return;}guard(()=>{if(!current().langs[lang]){if(!canEdit()){toast('当前身份不能为这篇文章创建译文。');return;}current().langs[lang]=langData(lang==='en'?'Untitled translation':'未命名译文','',1);}state.lang=lang;state.rights=false;state.release='idle';render();});return;}
  if(target?.dataset.editorView){state.editorView=target.dataset.editorView;render();return;}
  if(target?.dataset.workspace){const workspace=target.dataset.workspace;if(!accessibleWorkspace(workspace))return;closeModal();guard(()=>{resetWorkspaceContext();state.workspace=workspace;state.articleId=defaultArticle(workspace);state.lang='en';state.tab='all';state.query='';state.selected.clear();state.page=1;state.route='content';history.pushState(null,'','#content');render();});return;}
  if(target?.dataset.format){if(!canEdit())return;const field=document.getElementById('markdown');if(!field)return;const start=field.selectionStart,end=field.selectionEnd,selected=field.value.slice(start,end)||'text';const formats={bold:`**${selected}**`,italic:`*${selected}*`,heading:`\n## ${selected}\n`,quote:`\n> ${selected}\n`,link:`[${selected}](https://example.com)`,list:`\n- ${selected}\n`,code:`\n\`\`\`\n${selected}\n\`\`\`\n`};field.setRangeText(formats[target.dataset.format],start,end,'end');language().body=field.value;field.focus();updateEditFeedback();return;}
  if(event.target.closest('.row-check'))return;
  const row=event.target.closest('[data-article]');if(row)openArticle(row.dataset.article);
});
actions['open-selected']=()=>{closeModal();openArticle(state.articleId);};
document.addEventListener('input',event=>{const t=event.target;if(t.id==='search-input'){state.query=t.value;state.page=1;updateList();}if(t.id==='article-title'){language().title=t.value;resizeTitle();updateEditFeedback();}if(t.id==='markdown'){language().body=t.value;updateEditFeedback();}});
document.addEventListener('change',event=>{const t=event.target;if(t.id==='rights-confirm'){state.rights=t.checked;const button=document.querySelector('[data-action="confirm-publish"]');if(button)button.disabled=!t.checked;}if(t.classList.contains('row-check')){t.checked?state.selected.add(t.value):state.selected.delete(t.value);updateList();}if(t.id==='select-all'){filteredArticles().slice((state.page-1)*6,state.page*6).forEach(a=>t.checked?state.selected.add(a.id):state.selected.delete(a.id));updateList();}if(t.id==='demo-role'){state.release='idle';state.rights=false;state.role=t.value;state.selected.clear();if(current().creator!=='self'&&current().status==='submitted'&&!canPublish()){state.articleId='identity';state.lang='en';}closeModal();render();toast('当前演示身份：'+roleLabel());}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeModal();return;}const dialog=document.querySelector('.modal');if(event.key==='Tab'&&dialog){const focusable=[...dialog.querySelectorAll('button:not(:disabled),a[href],input,select,textarea,[tabindex="0"]')];const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}if((event.metaKey||event.ctrlKey)&&event.key==='k'){event.preventDefault();if(state.route==='content')document.getElementById('search-input')?.focus();}if((event.metaKey||event.ctrlKey)&&event.key==='s'&&state.route==='editor'){event.preventDefault();save();}});
window.addEventListener('resize',resizeTitle);
window.addEventListener('pagehide',()=>{clearTimeout(toastTimer);});
window.addEventListener('beforeunload',event=>{if(dirty()){event.preventDefault();event.returnValue='';}});
window.addEventListener('popstate',()=>handleLocationChange());
